query GetIssuesForState($sort: [IssueSortInput!], $filter: IssueFilter!, $first: Int, $after: String) {
  issues(filter: $filter, sort: $sort, first: $first, after: $after) {
    nodes {
      id
      identifier
      title
      priority
      estimate
      assignee {
        initials
      }
      state {
        id
        name
        color
        type
        position
      }
      cycle {
        id
        number
        name
        isActive
        isNext
        isPrevious
        isFuture
        isPast
      }
      team {
        id
        key
        cyclesEnabled
        activeCycle {
          number
        }
      }
      labels {
        nodes {
          id
          name
          color
        }
      }
      inverseRelations(first: 100) {
        nodes {
          id
          type
          issue {
            id
            identifier
            state {
              type
            }
          }
        }
      }
      updatedAt
    }
    pageInfo {
      hasNextPage
      endCursor
    }
  }
}
